import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts (use max in case of multiple rows)
    if len(watermark) == 0:
        high_ts = pd.Timestamp.min
    else:
        high_ts = watermark["high_ts"].max()

    # Build initial state from target_snapshot
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.user_id] = {
            "email": row.email,
            "status": row.status,
            "status_ts": row.status_ts,
        }

    # Filter events strictly after watermark
    filtered = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort deterministically by (event_ts, event_seq)
    filtered = filtered.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    seven_days = timedelta(days=7)

    for row in filtered.itertuples(index=False):
        uid = row.user_id
        op = row.op
        ts = row.event_ts
        email = row.email

        existing = state.get(uid)

        if op == "D":
            if existing is not None:
                preserved_email = existing["email"]
            else:
                preserved_email = email
            state[uid] = {
                "email": preserved_email,
                "status": "DELETED",
                "status_ts": ts,
            }
        elif op == "U":
            if existing is None:
                # new user -> upsert as ACTIVE
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            else:
                if existing["status"] == "ACTIVE":
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                else:  # DELETED
                    deletion_ts = existing["status_ts"]
                    if ts > deletion_ts + seven_days:
                        # resurrection
                        state[uid] = {
                            "email": email,
                            "status": "ACTIVE",
                            "status_ts": ts,
                        }
                    else:
                        # discard update, sticky deletion
                        pass
        # unknown op values are ignored (not specified)

    if len(state) == 0:
        result = pd.DataFrame(
            columns=["user_id", "email", "status", "status_ts"]
        )
    else:
        records = []
        for uid, info in state.items():
            records.append(
                {
                    "user_id": uid,
                    "email": info["email"],
                    "status": info["status"],
                    "status_ts": info["status_ts"],
                }
            )
        result = pd.DataFrame.from_records(records)
        result = result.sort_values(by="user_id", kind="mergesort").reset_index(drop=True)

    # Enforce dtypes
    result["user_id"] = result["user_id"].astype("int64")
    result["email"] = result["email"].astype(object)
    result["status"] = result["status"].astype(object)
    result["status_ts"] = pd.to_datetime(result["status_ts"])

    return {"new_snapshot": result}
